const crypto = require('crypto');

const headers = $input.first().json.headers || {};
const rawBody = $input.first().json.rawBody || JSON.stringify($input.first().json.body);
const body = $input.first().json.body;

const signatureHeader = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'];
const timestampHeader = headers['x-lendloop-timestamp'] || headers['X-LendLoop-Timestamp'];
const secret = $env.N8N_WEBHOOK_HMAC_SECRET;

if (!secret) {
  throw new Error('N8N_WEBHOOK_HMAC_SECRET environment variable is missing.');
}

if (!signatureHeader || !timestampHeader) {
  throw new Error('Unauthorized: Missing signature or timestamp header.');
}

const timestamp = parseInt(timestampHeader, 10);
const now = Date.now();
if (isNaN(timestamp) || Math.abs(now - timestamp) > 300000) {
  throw new Error('Unauthorized: Request timestamp expired or outside 5-minute tolerance.');
}

const expectedSignature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
const receivedHex = signatureHeader.replace(/^sha256=/, '').trim();

const bufExpected = Buffer.from(expectedSignature, 'hex');
const bufReceived = Buffer.from(receivedHex, 'hex');

if (bufReceived.length !== bufExpected.length || !crypto.timingSafeEqual(bufReceived, bufExpected)) {
  throw new Error('Unauthorized: HMAC signature mismatch. Payload may have been tampered with.');
}

if (body.eventType !== 'borrow_request.created' && body.eventType !== 'request.created') {
  throw new Error(`Routing Error: Invalid event type ${body.eventType} sent to Workflow A.`);
}

const lenderEmail = body.data.lender ? body.data.lender.email : null;
const lenderName = body.data.lender ? body.data.lender.displayName : 'Tool Owner';
const borrowerName = body.data.borrower ? body.data.borrower.displayName : 'Neighbor';
const toolName = body.data.tool ? body.data.tool.name : 'Tool';
const startDate = body.data.startDate || 'flexible';
const endDate = body.data.endDate || 'flexible';

const subject = `New Borrow Request: ${toolName}`;

const emailText = `Hello ${lenderName},\n\n${borrowerName} has requested to borrow your tool "${toolName}" on LendLoop.\n\nRequest Details:\n• Tool: ${toolName}\n• Borrower: ${borrowerName}\n• Start Date: ${startDate}\n• End Date: ${endDate}\n\nPlease log in to your LendLoop dashboard to review and respond to this request (approve or decline).\n\nThank you for being part of our neighborhood tool-sharing community!\n\nWarm regards,\nThe LendLoop Team`;

const emailHtml = `<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px;">\n  <h2 style="color: #2b6cb0;">New Borrow Request: ${toolName}</h2>\n  <p>Hello <strong>${lenderName}</strong>,</p>\n  <p><strong>${borrowerName}</strong> has requested to borrow your tool <strong>"${toolName}"</strong> on LendLoop.</p>\n  <div style="background-color: #f7fafc; padding: 15px; border-left: 4px solid #3182ce; margin: 20px 0;">\n    <p style="margin: 4px 0;"><strong>Tool:</strong> ${toolName}</p>\n    <p style="margin: 4px 0;"><strong>Borrower:</strong> ${borrowerName}</p>\n    <p style="margin: 4px 0;"><strong>Start Date:</strong> ${startDate}</p>\n    <p style="margin: 4px 0;"><strong>End Date:</strong> ${endDate}</p>\n  </div>\n  <p>Please log in to your LendLoop dashboard to review and approve or decline this request.</p>\n  <p>Thank you for supporting sustainable tool sharing in your neighborhood!</p>\n  <hr style="border: none; border-top: 1px solid #e2e8f0; margin: 20px 0;" />\n  <p style="color: #718096; font-size: 0.9em;">Warm regards,<br /><strong>The LendLoop Team</strong></p>\n</div>`;

return [
  {
    json: {
      eventId: body.eventId,
      requestId: body.data.requestId,
      toolName,
      borrowerName,
      lenderName,
      lenderEmail,
      recipientUserId: body.data.lender ? body.data.lender._id : null,
      startDate,
      endDate,
      subject,
      emailText,
      emailHtml,
      emailBody: emailText,
      idempotencyKey: `notif:req_created:${body.data.requestId}`
    }
  }
];

const crypto = require('crypto');
const extractData = $node["Verify HMAC & Extract Payload"].json;
const secret = $env.N8N_WEBHOOK_HMAC_SECRET;
const timestamp = Date.now().toString();

const summary = `Email delivered to lender (${extractData.lenderEmail}) for borrow request ${extractData.requestId}`;

const writeback = {
  idempotencyKey: extractData.idempotencyKey,
  requestId: extractData.requestId,
  eventType: 'borrow_request.created',
  recipientUserId: extractData.recipientUserId,
  result: 'sent',
  summary
};

const rawBody = JSON.stringify(writeback);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return [
  {
    json: {
      signature: `sha256=${signature}`,
      timestamp,
      body: rawBody,
      summary,
      result: 'sent'
    }
  }
];

const crypto = require('crypto');
const extractData = $node["Verify HMAC & Extract Payload"].json;
const currentInput = $input.first().json;
const secret = $env.N8N_WEBHOOK_HMAC_SECRET;
const timestamp = Date.now().toString();

const hasEmail = Boolean(extractData.lenderEmail && extractData.lenderEmail.trim());
const errorMsg = currentInput.error ? (currentInput.error.message || JSON.stringify(currentInput.error)) : null;

const summary = !hasEmail
  ? "Notification skipped: Lender email address not configured."
  : errorMsg
  ? `SMTP provider delivery failed: ${errorMsg.slice(0, 200)}`
  : "SMTP provider delivery failed.";

const writeback = {
  idempotencyKey: extractData.idempotencyKey,
  requestId: extractData.requestId,
  eventType: 'borrow_request.created',
  recipientUserId: extractData.recipientUserId,
  result: 'failed',
  summary
};

const rawBody = JSON.stringify(writeback);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return [
  {
    json: {
      signature: `sha256=${signature}`,
      timestamp,
      body: rawBody,
      summary,
      result: 'failed'
    }
  }
];

let originalResult = 'failed';
let originalSummary = 'Notification delivery failed.';

try {
  const successData = $node["Sign Success Write-Back"].json;
  if (successData && successData.result === 'sent') {
    originalResult = 'sent';
    originalSummary = successData.summary;
  }
} catch (e) {
  // Sign Success Write-Back did not execute
}

if (originalResult !== 'sent') {
  try {
    const failureData = $node["Sign Failure Write-Back"].json;
    if (failureData) {
      originalSummary = failureData.summary || 'Notification delivery failed.';
    }
  } catch (e) {
    // Sign Failure Write-Back did not execute
  }
}

const writebackResponse = $input.first().json || {};
const writebackOk = Boolean(writebackResponse.success === true);

if (originalResult === 'sent' && writebackOk) {
  return [
    {
      json: {
        delivered: true,
        result: 'sent',
        summary: originalSummary
      }
    }
  ];
} else {
  const failureSummary = !writebackOk && originalResult === 'sent'
    ? `Delivery succeeded but Convex activity writeback failed: ${JSON.stringify(writebackResponse)}`
    : originalSummary;
  return [
    {
      json: {
        delivered: false,
        result: 'failed',
        summary: failureSummary
      }
    }
  ];
}
